import { Alert } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ButtonGroup } from "@/components/ui/button-group";
import { Panel, PanelDescription, PanelHeader, PanelTitle } from "@/components/ui/panel";
import { Progress } from "@/components/ui/progress";
import { ParticipantStatus } from "@/components/game/participant-status";
import { RoomCodeDisplay } from "@/components/display/room-code-display";
import { cn } from "@/lib/cn";
import type { ParticipantSummary, SessionSummary, StageStatus } from "@/types/game";

export interface FacilitatorLobbyProps {
  session: SessionSummary;
  participants: ParticipantSummary[];
  status: StageStatus;
  startDisabledReason?: string;
  showStartConfirm?: boolean;
  onStart: () => void;
  onCancelStart?: () => void;
  onConfirmStart?: () => void;
  className?: string;
}

function FacilitatorLobby({
  session,
  participants,
  status,
  startDisabledReason,
  showStartConfirm = false,
  onStart,
  onCancelStart,
  onConfirmStart,
  className,
}: FacilitatorLobbyProps) {
  const expected = session.expectedParticipantCount ?? participants.length;
  const readyCount = participants.filter((participant) => participant.readiness === "ready").length;
  const disconnectedCount = participants.filter(
    (participant) => participant.connection !== "connected",
  ).length;
  const progressValue = expected > 0 ? Math.round((participants.length / expected) * 100) : 0;
  const canStart = status === "ready" && !startDisabledReason;

  return (
    <div className={cn("grid gap-4 lg:grid-cols-[280px_minmax(0,1fr)]", className)}>
      <Panel elevation="raised" className="space-y-4">
        <PanelHeader>
          <PanelTitle>Session control</PanelTitle>
          <PanelDescription>
            Participants currently see the join/lobby screens. The shared display shows the room
            code.
          </PanelDescription>
        </PanelHeader>

        <RoomCodeDisplay code={session.code} label="Room code" />
        <div className="flex flex-wrap gap-2">
          <Badge intent="information">Stage: Lobby</Badge>
          <Badge intent={status === "ready" ? "success" : "default"}>Status: {status}</Badge>
        </div>

        <Progress value={progressValue} label={`Joined ${participants.length} of ${expected}`} />

        {disconnectedCount > 0 ? (
          <Alert intent="warning" title={`${disconnectedCount} participant connection issue`}>
            Review the participant list before advancing. Disconnected participants may miss the
            start cue.
          </Alert>
        ) : null}

        {showStartConfirm ? (
          <Alert intent="warning" title="Start the session?">
            This advances every interface out of the lobby. Confirm only when the room is ready.
            <ButtonGroup className="mt-3">
              <Button type="button" intent="primary" onClick={onConfirmStart}>
                Confirm start
              </Button>
              <Button type="button" intent="ghost" onClick={onCancelStart}>
                Cancel
              </Button>
            </ButtonGroup>
          </Alert>
        ) : (
          <ButtonGroup orientation="vertical">
            <Button type="button" intent="primary" size="lg" disabled={!canStart} onClick={onStart}>
              Start session
            </Button>
            {!canStart ? (
              <p className="text-[length:var(--type-scale-label)] text-muted-foreground">
                {startDisabledReason ?? "Start becomes available when the lobby status is ready."}
              </p>
            ) : null}
          </ButtonGroup>
        )}
      </Panel>

      <Panel elevation="subtle" padding="md">
        <PanelHeader>
          <PanelTitle>Participants</PanelTitle>
          <PanelDescription>
            {readyCount} ready · {participants.length} joined
          </PanelDescription>
        </PanelHeader>

        {participants.length === 0 ? (
          <Alert intent="information" title="No participants connected">
            Share the room code on the shared display. New joiners will appear here.
          </Alert>
        ) : (
          <ul className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">
            {participants.map((participant) => (
              <li key={participant.id}>
                <ParticipantStatus
                  displayName={participant.displayName}
                  connection={participant.connection}
                  readiness={participant.readiness}
                />
              </li>
            ))}
          </ul>
        )}
      </Panel>
    </div>
  );
}

FacilitatorLobby.displayName = "FacilitatorLobby";

export { FacilitatorLobby };

import { Badge } from "@/components/ui/badge";
import { Panel } from "@/components/ui/panel";
import { WaitingState } from "@/components/game/waiting-state";
import { DisplayHeading } from "@/components/display/display-heading";
import { ParticipantCountDisplay } from "@/components/display/participant-count-display";
import { RoomCodeDisplay } from "@/components/display/room-code-display";
import { cn } from "@/lib/cn";
import type { SessionSummary, StageStatus } from "@/types/game";

export interface SharedDisplayLobbyProps {
  session: SessionSummary;
  status: StageStatus;
  instruction?: string;
  className?: string;
}

function SharedDisplayLobby({
  session,
  status,
  instruction = "Open the game on your phone and enter this code",
  className,
}: SharedDisplayLobbyProps) {
  const isReady = status === "ready";

  return (
    <div
      className={cn(
        "mx-auto flex min-h-[70vh] w-full max-w-content flex-col items-center justify-center gap-[var(--section-gap)] px-8",
        className,
      )}
    >
      <DisplayHeading eyebrow={session.title ?? "GameScience session"}>
        {isReady ? "Ready to begin" : "Join the session"}
      </DisplayHeading>

      <Panel elevation="raised" padding="lg" className="w-full max-w-4xl space-y-8">
        <RoomCodeDisplay code={session.code} />
        <p className="text-center text-[length:var(--type-scale-body)] text-muted-foreground">
          {instruction}
        </p>
        <ParticipantCountDisplay
          count={session.participantCount}
          expected={session.expectedParticipantCount}
        />
        <div className="flex justify-center">
          <Badge intent={isReady ? "success" : "information"}>
            {isReady ? "All participants ready" : "Waiting for participants"}
          </Badge>
        </div>
      </Panel>

      {!isReady ? (
        <WaitingState
          title="Waiting for players"
          description="Private participant details are never shown on this display."
          loading
        />
      ) : (
        <WaitingState
          title="Stand by for facilitator start"
          description="The shared display will advance with the room."
          loading={false}
        />
      )}
    </div>
  );
}

SharedDisplayLobby.displayName = "SharedDisplayLobby";

export { SharedDisplayLobby };

import type { HTMLAttributes } from "react";
import { cn } from "@/lib/cn";

export interface DisplayHeadingProps extends HTMLAttributes<HTMLHeadingElement> {
  as?: "h1" | "h2" | "h3";
  eyebrow?: string;
}

function DisplayHeading({
  as: Comp = "h1",
  eyebrow,
  className,
  children,
  ...props
}: DisplayHeadingProps) {
  return (
    <div className={cn("space-y-2 text-center", className)}>
      {eyebrow ? <p className="gs-label text-muted-foreground">{eyebrow}</p> : null}
      <Comp className="gs-display text-foreground" {...props}>
        {children}
      </Comp>
    </div>
  );
}

DisplayHeading.displayName = "DisplayHeading";

export { DisplayHeading };

import { cn } from "@/lib/cn";

export interface ParticipantCountDisplayProps {
  count: number;
  expected?: number;
  label?: string;
  className?: string;
}

function ParticipantCountDisplay({
  count,
  expected,
  label = "Participants connected",
  className,
}: ParticipantCountDisplayProps) {
  const value = expected != null ? `${count} / ${expected}` : String(count);

  return (
    <div className={cn("text-center", className)} aria-live="polite">
      <p className="gs-label text-muted-foreground">{label}</p>
      <p className="gs-display mt-1 font-display text-foreground">{value}</p>
    </div>
  );
}

ParticipantCountDisplay.displayName = "ParticipantCountDisplay";

export { ParticipantCountDisplay };

export { DisplayHeading, type DisplayHeadingProps } from "./display-heading";
export {
  ParticipantCountDisplay,
  type ParticipantCountDisplayProps,
} from "./participant-count-display";
export { RoomCodeDisplay, type RoomCodeDisplayProps } from "./room-code-display";
